    31→public fun enter_market_return<MarketType>(app: &ProtocolApp, market: &mut Market<MarketType>, ctx: &mut TxContext): obligation::ObligationOwnerCap {
    32→    enter_market_inner<MarketType>(app, market, lending_default_emode_group(), ctx)
    33→}
    34→
    35→/// Being restrictive on who can join with emode. Consider lifting this restriction in future releases.
    36→public fun enter_market_with_emode<MarketType>(app: &ProtocolApp, cap: &PackageCallerCap, market: &mut Market<MarketType>, emode_group: u8, ctx: &mut TxContext): obligation::ObligationOwnerCap {
    37→    app.ensure_has_permission(object::id(cap), protocol::whitelist_admin::enter_market_with_emode());
    38→    enter_market_inner<MarketType>(app, market, emode_group, ctx)
    39→}
    40→
    41→fun enter_market_inner<MarketType>(app: &ProtocolApp, market: &mut Market<MarketType>, emode_group: u8, ctx: &mut TxContext): obligation::ObligationOwnerCap {
    42→    app.ensure_version_matches();
    43→    app.validate_market<MarketType>(market);
